  // checked after the heuristic freshness branches above so that responses which
  // already have a freshness lifetime keep it.
  // https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2.4
  if (
    cacheControlDirectives['no-cache'] &&
