cat > /tmp/repro.mjs <<'EOF'
import { createServer } from 'node:http'
import { once } from 'node:events'
import { Client, interceptors } from './index.js'

async function run (cc, extra = {}) {
  const reqs = []
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    reqs.push(req.headers['if-none-match'] ? 'conditional' : 'full')
    if (req.headers['if-none-match'] === '"asd"') { res.statusCode = 304; res.end(); return }
    res.setHeader('cache-control', cc)
    res.setHeader('etag', '"asd"')
    for (const [k, v] of Object.entries(extra)) res.setHeader(k, v)
    res.end('hello')
  }).listen(0)
  await once(server, 'listening')
  const origin = `http://localhost:${server.address().port}`
  const client = new Client(origin).compose(interceptors.cache())
  for (let i = 0; i < 2; i++) {
    const res = await client.request({ origin, method: 'GET', path: '/' })
    const body = await res.body.text()
    if (body !== 'hello') throw new Error('bad body: ' + JSON.stringify(body))
  }
  await client.close(); server.close()
  console.log(cc, JSON.stringify(extra), '=>', reqs.join(', '))
}

await run('no-cache')
await run('max-age=0')
await run('no-cache', { 'last-modified': new Date(0).toUTCString() })
await run('no-store')
EOF
node /tmp/repro.mjs
